package repo

import (
  "context"
  "time"

  "github.com/jmoiron/sqlx"
)

type User struct {
  ID        int64
  Email     string
  CreatedAt time.Time
}

type Repo struct {
  db *sqlx.DB
}

func (r *Repo) Find(ctx context.Context, id int64) (*User, error) {
  var u User
  err := r.db.GetContext(ctx, &u, "SELECT id, email, created_at FROM users WHERE id = $1", id)
  if err != nil {
    return nil, err
  }
  return &u, nil
}

func (r *Repo) Recent(ctx context.Context, limit int) ([]User, error) {
  var users []User
  err := r.db.SelectContext(ctx, &users, "SELECT id, email, created_at FROM users ORDER BY created_at DESC LIMIT $1", limit)
  return users, err
}

