type User struct {
  ID        int64     `db:"id"`
  Email     string    `db:"email"`
  CreatedAt time.Time `db:"created_at"`
}

func (r *Repo) Create(ctx context.Context, u *User) error {
  res, err := r.db.NamedExecContext(ctx,
    "INSERT INTO users (email, created_at) VALUES (:email, :created_at)", u)
  if err != nil {
    return err
  }
  u.ID, err = res.LastInsertId()
  return err
}

func (r *Repo) UpdateEmail(ctx context.Context, u *User) error {
  _, err := r.db.NamedExecContext(ctx, "UPDATE users SET email = :email WHERE id = :id", u)
  return err
}

func (r *Repo) Create(ctx context.Context, u *User) error {
  stmt, err := r.db.PrepareNamedContext(ctx,
    "INSERT INTO users (email, created_at) VALUES (:email, :created_at) RETURNING id")
  if err != nil {
    return err
  }
  defer stmt.Close()
  return stmt.GetContext(ctx, &u.ID, u)
}
